/**
 * Content-loop device B for the Bid Scanner page.
 *
 * /bid-scanner/ is a static file (public/bid-scanner/index.html), not an
 * Astro page, so its related-post list cannot be generated by a template.
 * This build hook injects it into the built file instead: the two most
 * recent published posts tagged adu-bid / contractor-bid / contractor /
 * adu-quote (excluding the post already linked in the file), plus a
 * breadcrumb. Same tag rule as src/lib/related.ts, same publish rule as
 * postFilter (drafts excluded, pubDatetime minus the 15-minute margin).
 *
 * Fail-open by design: any error only logs a warning and leaves the file
 * untouched, so a broken injection can never break a build.
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { join } from "node:path";

const BID_TAGS = new Set([
  "adu-bid",
  "contractor-bid",
  "contractor",
  "adu-quote",
]);
const ALREADY_LINKED = "how-to-read-adu-bid";
const PUBLISH_MARGIN_MS = 15 * 60 * 1000;

function escapeHtml(s: string) {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function parseFrontmatter(src: string) {
  const m = /^---\n([\s\S]*?)\n---/.exec(src);
  if (!m) return null;
  const fm = m[1];
  const field = (name: string) => {
    const r = new RegExp(`^${name}:\\s*"(.*)"\\s*$`, "m").exec(fm);
    return r ? r[1] : null;
  };
  const tagsRaw = /^tags:\s*\[(.*?)\]/m.exec(fm);
  const tags = tagsRaw
    ? [...tagsRaw[1].matchAll(/"([^"]+)"/g)].map(x =>
        x[1].toLowerCase().replace(/\s+/g, "-")
      )
    : [];
  const draft = /^draft:\s*true\s*$/m.test(fm);
  const pubRaw = /^pubDatetime:\s*(.+?)\s*$/m.exec(fm);
  return {
    title: field("title"),
    description: field("description"),
    tags,
    draft,
    pub: pubRaw ? new Date(pubRaw[1]).getTime() : NaN,
  };
}

export const loopBidScanner = {
  name: "content-loop-bid-scanner",
  hooks: {
    "astro:build:done": ({ dir }: { dir: URL }) => {
      try {
        const outDir = fileURLToPath(dir);
        const htmlPath = join(outDir, "bid-scanner", "index.html");
        let html = readFileSync(htmlPath, "utf8");

        const postsDir = join(process.cwd(), "src", "content", "posts");
        const now = Date.now();
        const candidates: {
          slug: string;
          title: string;
          description: string;
          pub: number;
        }[] = [];
        for (const file of readdirSync(postsDir)) {
          if (!file.endsWith(".md") && !file.endsWith(".mdx")) continue;
          const slug = file.replace(/\.(md|mdx)$/, "");
          if (slug === ALREADY_LINKED) continue;
          const fm = parseFrontmatter(
            readFileSync(join(postsDir, file), "utf8")
          );
          if (!fm || !fm.title || !fm.description) continue;
          if (fm.draft) continue;
          if (Number.isNaN(fm.pub)) continue;
          if (now <= fm.pub - PUBLISH_MARGIN_MS) continue;
          if (!fm.tags.some(t => BID_TAGS.has(t))) continue;
          candidates.push({
            slug,
            title: fm.title,
            description: fm.description,
            pub: fm.pub,
          });
        }
        candidates.sort((a, b) => b.pub - a.pub);
        const picked = candidates.slice(0, 2);

        // Breadcrumb (device C) right after <main>.
        const mainAnchor = '<main class="wrap">';
        if (!html.includes(mainAnchor)) {
          console.warn(
            "[content-loop] bid-scanner: <main> anchor not found, skipping injection"
          );
          return;
        }
        html = html.replace(
          mainAnchor,
          `${mainAnchor}\n  <nav aria-label="breadcrumb" class="small"><a href="/">Home</a> &raquo; <a href="/tools/">Tools</a> &raquo; Bid Scanner</nav>`
        );

        // Related posts (device B) after the already-linked bid post.
        const linkAnchor = `href="/posts/${ALREADY_LINKED}/"`;
        const anchorIdx = html.indexOf(linkAnchor);
        if (anchorIdx === -1) {
          console.warn(
            "[content-loop] bid-scanner: related-list anchor not found, skipping post injection"
          );
          writeFileSync(htmlPath, html);
          return;
        }
        const liClose = html.indexOf("</li>", anchorIdx);
        if (liClose === -1) {
          console.warn(
            "[content-loop] bid-scanner: </li> anchor not found, skipping post injection"
          );
          writeFileSync(htmlPath, html);
          return;
        }
        const items = picked
          .map(
            p =>
              `      <li><a href="/posts/${p.slug}/">${escapeHtml(p.title)}</a> — ${escapeHtml(p.description)}</li>`
          )
          .join("\n");
        html =
          html.slice(0, liClose + "</li>".length) +
          "\n" +
          items +
          html.slice(liClose + "</li>".length);
        writeFileSync(htmlPath, html);
        console.log(
          `[content-loop] bid-scanner: injected ${picked.length} related post(s) + breadcrumb`
        );
      } catch (err) {
        console.warn("[content-loop] bid-scanner injection failed:", err);
      }
    },
  },
};
